<?php
namespace ABPlatform;
/** Eligibility is local and deterministic; attributes are supplied explicitly by the host. */
final class Experience {
 public static function valid($r) {
  if(!is_array($r)||array_diff(array_keys($r),array('mode','pages','audience','schedule','exclusion','factors','guardrail'))){return false;}
  if(isset($r['mode'])&&!in_array($r['mode'],array('ab','multipage','multivariate','personalization'),true)){return false;}
  if(isset($r['pages'])){if(!is_array($r['pages'])||count($r['pages'])>20){return false;}foreach($r['pages'] as $p){if(!is_array($p)||!isset($p['url'],$p['match'])||!is_string($p['url'])||trim($p['url'])===''||strlen($p['url'])>2048||!in_array($p['match'],array('contains','equals','starts-with'),true)){return false;}}}
  if(isset($r['audience'])){if(!is_array($r['audience'])||count($r['audience'])>20){return false;}foreach($r['audience'] as $a){if(!is_array($a)||!isset($a['key'],$a['operator'])||!array_key_exists('value',$a)||!is_string($a['key'])||!preg_match('/^[a-zA-Z][a-zA-Z0-9_.-]{0,63}$/D',$a['key'])||!in_array($a['operator'],array('eq','neq','contains','gte','lte','exists'),true)||!(is_string($a['value'])||is_int($a['value'])||is_float($a['value'])||is_bool($a['value']))){return false;}}}
  if(isset($r['schedule'])){if(!is_array($r['schedule'])||array_diff(array_keys($r['schedule']),array('startsAt','endsAt'))){return false;}foreach(array('startsAt','endsAt') as $k){if(isset($r['schedule'][$k])&&(!is_string($r['schedule'][$k])||!preg_match('/^\d{4}-\d{2}-\d{2}T/',$r['schedule'][$k])||strtotime($r['schedule'][$k])===false)){return false;}}if(isset($r['schedule']['startsAt'],$r['schedule']['endsAt'])&&strtotime($r['schedule']['startsAt'])>=strtotime($r['schedule']['endsAt'])){return false;}}
  if(isset($r['exclusion'])){$e=$r['exclusion'];if(!is_array($e)||!isset($e['group'],$e['from'],$e['to'])||!is_string($e['group'])||!preg_match('/^[a-zA-Z0-9_-]{1,80}$/D',$e['group'])||!is_int($e['from'])||!is_int($e['to'])||$e['from']<0||$e['to']>10000||$e['from']>=$e['to']){return false;}}
  if(isset($r['factors'])){if(!is_array($r['factors'])||count($r['factors'])>4){return false;}$names=array();$count=1;foreach($r['factors'] as $f){if(!is_array($f)||!isset($f['name'],$f['options'])||!is_string($f['name'])||trim($f['name'])===''||strlen($f['name'])>64||!is_array($f['options'])||count($f['options'])<2||count($f['options'])>8||in_array($f['name'],$names,true)){return false;}$names[]=$f['name'];$seen=array();foreach($f['options'] as $o){if(!is_string($o)||trim($o)===''||strlen($o)>64||in_array($o,$seen,true)){return false;}$seen[]=$o;}$count*=count($f['options']);}if($count>16){return false;}}
  if(isset($r['guardrail'])){$g=$r['guardrail'];if(!is_array($g)||!isset($g['enabled'],$g['action'],$g['minimumVisitors'],$g['lossPercent'])||!is_bool($g['enabled'])||!in_array($g['action'],array('notify','pause'),true)||!is_int($g['minimumVisitors'])||$g['minimumVisitors']<100||$g['minimumVisitors']>10000000||!(is_int($g['lossPercent'])||is_float($g['lossPercent']))||$g['lossPercent']<1||$g['lossPercent']>99){return false;}}
  return true;
 }
 public static function matchesPage($url,$page) {if(empty($page['url'])){return true;}if(!is_string($url)){return false;}switch($page['match']){case 'equals':return $url===$page['url'];case 'starts-with':return strpos($url,$page['url'])===0;case 'contains':return strpos($url,$page['url'])!==false;default:return false;}}
 public static function eligible($experiment,$options) {
  $r=$experiment['experience']??array();if(!self::valid($r)){return false;}$url=$options['url']??'';
  if(!empty($r['pages'])){$matched=false;foreach($r['pages'] as $page){if(self::matchesPage($url,$page)){$matched=true;break;}}if(!$matched){return false;}}elseif(!self::matchesPage($url,$experiment['targeting']??array())){return false;}
  $schedule=$r['schedule']??array();if(!empty($schedule['startsAt'])&&time()<strtotime($schedule['startsAt'])){return false;}if(!empty($schedule['endsAt'])&&time()>=strtotime($schedule['endsAt'])){return false;}
  $attributes=$options['attributes']??array();foreach($r['audience']??array() as $rule){$exists=array_key_exists($rule['key'],$attributes);$value=$exists?$attributes[$rule['key']]:null;$expected=$rule['value'];if($rule['operator']==='exists'){if($exists!==($expected===true||$expected==='true')){return false;}continue;}if(!$exists){return false;}switch($rule['operator']){case 'eq':$ok=((is_int($value)||is_float($value))&&(is_int($expected)||is_float($expected)) ? $value==$expected : $value===$expected);break;case 'neq':$ok=!((is_int($value)||is_float($value))&&(is_int($expected)||is_float($expected)) ? $value==$expected : $value===$expected);break;case 'contains':$ok=is_string($value)&&is_string($expected)&&strpos($value,$expected)!==false;break;case 'gte':$ok=(is_int($value)||is_float($value))&&(is_int($expected)||is_float($expected))&&$value>=$expected;break;case 'lte':$ok=(is_int($value)||is_float($value))&&(is_int($expected)||is_float($expected))&&$value<=$expected;break;default:$ok=false;}if(!$ok){return false;}}
  if(isset($r['exclusion'])){$e=$r['exclusion'];$bucket=Evaluator::hashBucket(Evaluator::canonicalSeed('traffic','exclusion:'.$options['projectKey'].':'.$options['environment'].':'.$e['group'],1,$options['visitorId']));if($bucket<$e['from']||$bucket>=$e['to']){return false;}}
  return true;
 }
}
